"""Offline payload compilation, client replay and origin evidence audit.

Reads exactly one UTF-8 JSON object on stdin, validates the whole document,
compiles compressed byte definitions and templates, replays the decoded client
events on the offline clock, audits the compressed origin captures and writes
one JSON object on stdout.
"""
import gc
import json
import math
import re
import sys
from pathlib import Path

# The local no-Docker worker stages the same pinned wheels here. In the public
# image the packages are installed normally and this directory is unnecessary.
if Path('/opt/h3deps').is_dir():
    sys.path.insert(0, '/opt/h3deps')

sys.setrecursionlimit(60000)

from schema import compile_cases
from modules.byte_program import MAX, Context, is_definition_name
from modules.fuzz_adapter import FuzzExecutor
from modules.capture_audit import TOKEN, audit_channels, case_origin

NAME = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z', re.ASCII)
SEED = frozenset('abcdefghijklmnopqrstuvwxyz'
                 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-')
STDIN_LIMIT = 8 * 1024 * 1024
DEFINITIONS_LIMIT = 8192
CASES_LIMIT = 2000
CHANNELS_LIMIT = 256
PARTS_LIMIT = 50000
FRAMES_LIMIT = 50000
PAIRS_LIMIT = 32768
BLOCK_PAIRS_LIMIT = 128
EXPECT_LIMIT = 8192
TEMPLATE_LIMIT = 65536
EXPRESSION_LIMIT = 8192
STREAM_LIMIT = (1 << 32) - 1


def exact(obj, keys):
    if type(obj) is not dict or set(obj) != set(keys):
        raise ValueError('object keys')


def integer(value, minimum=0, maximum=MAX):
    if type(value) is not int or isinstance(value, bool) \
            or not minimum <= value <= maximum:
        raise ValueError('integer')
    return value


def sequence(value, maximum):
    if type(value) is not list or len(value) > maximum:
        raise ValueError('array')
    return value


def text(value, maximum=TEMPLATE_LIMIT):
    if type(value) is not str or len(value) > maximum:
        raise ValueError('string')
    value.encode('utf8')
    return value


def pairs(items):
    out = {}
    for key, value in items:
        if key in out:
            raise ValueError('duplicate key')
        out[key] = value
    return out


def bad_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError('nonfinite JSON number')
    return result


def visible_ascii(value):
    data = value.encode('ascii')
    if not data:
        raise ValueError('empty identity')
    if any(byte < 33 or byte > 126 for byte in data):
        raise ValueError('identity whitespace')
    return data


def compile_definitions(document):
    rows = sequence(document['definitions'], DEFINITIONS_LIMIT)
    definitions = []
    for row in rows:
        sequence(row, 2)
        if len(row) != 2:
            raise ValueError('definition pair')
        name = row[0]
        if not is_definition_name(name):
            raise ValueError('definition name')
        source = text(row[1], EXPRESSION_LIMIT)
        definitions.append((name, source))
    return definitions


def compile_cases_input(document):
    cases = sequence(document['cases'], CASES_LIMIT)
    names = set()
    budget = 0
    fields = 0
    prepared = []
    for case in cases:
        exact(case, ['name', 'frames', 'expect'])
        name = text(case['name'], 32)
        if not NAME.fullmatch(name) or name in names:
            raise ValueError('case name')
        names.add(name)
        frames = sequence(case['frames'], FRAMES_LIMIT)
        budget += len(frames)
        pauses = 0
        for frame in frames:
            kind = validate_frame(frame)
            if kind == 'sleep':
                pauses += frame['Time_to_Stop']
            elif kind == 'headers':
                if 'headers_kv' in frame:
                    fields += len(frame['headers_kv'])
                else:
                    fields += len(frame['data_to_transfered'])
        if pauses + document['timeout_ms'] > MAX:
            raise ValueError('virtual time budget')
        expect = case['expect']
        exact(expect, ['method', 'target', 'host'])
        identity = {}
        for key in ('method', 'target', 'host'):
            identity[key] = visible_ascii(text(expect[key], EXPECT_LIMIT))
        if TOKEN.fullmatch(identity['method']) is None:
            raise ValueError('expected method')
        prepared.append({'name': name, 'frames': frames, 'expect': identity})
    return prepared, names, budget, fields


def validate_frame(frame):
    if type(frame) is not dict:
        raise ValueError('frame')
    kind = frame.get('Type')
    if type(kind) is not str:
        raise ValueError('frame type')
    if kind == 'headers':
        mapping = 'headers_kv' in frame
        listed = 'data_to_transfered' in frame
        if mapping == listed:
            raise ValueError('header source')
        keys = {'Type', 'headers_kv' if mapping else 'data_to_transfered'}
        if 'End_Stream' in frame:
            if type(frame['End_Stream']) is not bool:
                raise ValueError('End_Stream')
            keys.add('End_Stream')
        if set(frame) != keys:
            raise ValueError('frame keys')
        if mapping:
            source = frame['headers_kv']
            if type(source) is not dict or len(source) > BLOCK_PAIRS_LIMIT:
                raise ValueError('header mapping')
            for name, value in source.items():
                text(name)
                text(value)
        else:
            source = sequence(frame['data_to_transfered'], BLOCK_PAIRS_LIMIT)
            for pair in source:
                if type(pair) is not list or len(pair) != 2:
                    raise ValueError('header pair')
                text(pair[0])
                text(pair[1])
    elif kind in ('data', 'datagram'):
        keys = {'Type', 'data_to_transfered'}
        if 'End_Stream' in frame:
            if type(frame['End_Stream']) is not bool:
                raise ValueError('End_Stream')
            keys.add('End_Stream')
        if set(frame) != keys:
            raise ValueError('frame keys')
        text(frame['data_to_transfered'])
    elif kind == 'sleep':
        if set(frame) != {'Type', 'Time_to_Stop'}:
            raise ValueError('frame keys')
        integer(frame['Time_to_Stop'], 0, MAX)
    else:
        raise ValueError('frame type')
    return kind


def compile_events(document, context, budget, fields):
    records = sequence(document['events'], FRAMES_LIMIT)
    budget += len(records)
    events = []
    for index, record in enumerate(records):
        if type(record) is not dict:
            raise ValueError('event')
        kind = record.get('kind')
        if kind == 'close':
            keys = {'at', 'kind'}
        elif kind == 'headers':
            keys = {'at', 'kind', 'stream', 'fields', 'end'}
        elif kind == 'data':
            keys = {'at', 'kind', 'stream', 'data', 'end'}
        else:
            raise ValueError('event kind')
        if set(record) != keys:
            raise ValueError('event keys')
        integer(record['at'], 0, MAX)
        row = {'at': record['at'], 'kind': kind}
        if kind != 'close':
            integer(record['stream'], 0, STREAM_LIMIT)
            if type(record['end']) is not bool:
                raise ValueError('event end')
            row['stream'] = record['stream']
            row['end'] = record['end']
        if kind == 'headers':
            source = sequence(record['fields'], BLOCK_PAIRS_LIMIT)
            fields += len(source)
            compiled = []
            for slot, pair in enumerate(source):
                if type(pair) is not list or len(pair) != 2:
                    raise ValueError('event field pair')
                compiled.append((
                    context.template(text(pair[0]), 'event/%d/h/%d/n' % (index, slot)),
                    context.template(text(pair[1]), 'event/%d/h/%d/v' % (index, slot))))
            row['fields'] = compiled
        elif kind == 'data':
            row['data'] = context.template(text(record['data']),
                                           'event/%d/data' % index)
        events.append(row)
    return events, budget, fields


def compile_channels(document, context, case_names, budget):
    rows = sequence(document['channels'], CHANNELS_LIMIT)
    names = set()
    compiled = []
    for index, channel in enumerate(rows):
        exact(channel, ['name', 'parts'])
        name = text(channel['name'], 32)
        if not NAME.fullmatch(name) or name in names:
            raise ValueError('channel name')
        names.add(name)
        parts = sequence(channel['parts'], FRAMES_LIMIT)
        budget += len(parts)
        out = []
        for position, part in enumerate(parts):
            exact(part, ['case', 'data'])
            owner = part['case']
            if owner is not None and (type(owner) is not str
                                      or owner not in case_names):
                raise ValueError('owner label')
            out.append((owner, context.template(text(part['data']),
                                                'channel/%d/part/%d/data'
                                                % (index, position))))
        compiled.append((name, out))
    return compiled, budget


def compile_document(document):
    exact(document, ['seed', 'definitions', 'timeout_ms', 'cases', 'events',
                     'channels'])
    seed = text(document['seed'], 64)
    if any(char not in SEED for char in seed):
        raise ValueError('seed')
    timeout = integer(document['timeout_ms'], 1, 10 ** 9)
    definitions = compile_definitions(document)
    context = Context(definitions, seed)
    prepared, case_names, budget, fields = compile_cases_input(document)
    events, budget, fields = compile_events(document, context, budget, fields)
    channels, budget = compile_channels(document, context, case_names, budget)
    if budget > PARTS_LIMIT:
        raise ValueError('combined budget')
    if fields > PAIRS_LIMIT:
        raise ValueError('header pair budget')
    payload = compile_cases(prepared, context)
    expectations = {}
    for case in prepared:
        expectations[case['name']] = case['expect']
    return payload, events, channels, expectations


def run(document):
    payload, events, channels, expectations = compile_document(document)
    executor = FuzzExecutor()
    records = executor.send_payload(payload, events, document['timeout_ms'])
    by_name = {record['name']: record for record in records}
    channel_records, origin = audit_channels(channels, expectations, by_name)
    cases = []
    for record in records:
        count, flags = case_origin(record['name'], origin, record)
        row = dict(record)
        row['origin_count'] = count
        row['flags'] = flags
        cases.append(row)
    return {'cases': cases, 'channels': channel_records}


def main():
    gc.disable()
    try:
        raw = sys.stdin.buffer.read(STDIN_LIMIT + 1)
        if len(raw) > STDIN_LIMIT:
            raise ValueError('input bytes')
        document = json.loads(raw.decode('utf8'), object_pairs_hook=pairs,
                              parse_constant=bad_constant, parse_float=finite_float)
        result = run(document)
    except Exception:
        result = {'error': 'input'}
    encoded = json.dumps(result, ensure_ascii=True, separators=(',', ':'),
                         allow_nan=False).encode('ascii')
    sys.stdout.buffer.write(encoded + b'\n')
    sys.stdout.buffer.flush()


if __name__ == '__main__':
    main()
PYEOF
cd /workspace/project && python3 -B main.py < /workspace/sample.json
